// The last stored leg of a Recovery asset leaves through the public forfeit,
// as a flat pending obligation or as a live position. Floored A indices can
// leave up to three atoms of effective OI on each side that no leg owns. Once
// the asset is legless the forfeit drops that residue and starts both side
// resets, so no side keeps effective OI without loss weight (spec.md:953), and
// the forfeit moves no value.
#[kani::proof]
#[kani::unwind(24)]
#[kani::solver(cadical)]
fn proof_v16_public_recovery_forfeit_of_last_leg_resets_legless_asset() {
    use percolator::v16::DeadLegForfeitOutcomeV16;

    let is_short: bool = kani::any();
    let size_units: u8 = kani::any();
    let weight_units: u8 = kani::any();
    let long_residue: u8 = kani::any();
    let short_residue: u8 = kani::any();
    kani::assume(size_units <= 3);
    kani::assume((size_units.max(1)..=4).contains(&weight_units));
    kani::assume(long_residue <= 3 && short_residue <= 3);
    let side = if is_short {
        SideV16::Short
    } else {
        SideV16::Long
    };
    // Size zero is a flat pending obligation, which owns no effective OI. A
    // live leg opened at ADL_ONE owns ceil(basis * A / ADL_ONE) == basis at
    // these A indices and carries at least its basis weight.
    let basis = size_units as u128 * POS_SCALE;
    let weight = weight_units as u128 * POS_SCALE;

    let (mut header, mut markets, mut account_header) = one_market_view_fixture();
    let market_id = markets[0].engine.asset.market_id.get();
    header.vault = V16PodU128::new(7 * POS_SCALE);
    header.c_tot = V16PodU128::new(5 * POS_SCALE);
    header.insurance = V16PodU128::new(2 * POS_SCALE);
    header.resolved_payout_blocker_count = V16PodU64::new(1);
    header.materialized_portfolio_count = V16PodU64::new(1);
    account_header.capital = V16PodU128::new(5 * POS_SCALE);
    let mut asset = markets[0].engine.asset.try_to_runtime().unwrap();
    asset.lifecycle = AssetLifecycleV16::Recovery;
    asset.a_long = 999_999_940_959_838;
    asset.a_short = 999_999_952_247_457;
    asset.oi_eff_long_q = long_residue as u128;
    asset.oi_eff_short_q = short_residue as u128;
    match side {
        SideV16::Long => {
            asset.oi_eff_long_q += basis;
            asset.stored_pos_count_long = 1;
            asset.pending_obligation_count_long = u64::from(basis == 0);
            asset.loss_weight_sum_long = weight;
        }
        SideV16::Short => {
            asset.oi_eff_short_q += basis;
            asset.stored_pos_count_short = 1;
            asset.pending_obligation_count_short = u64::from(basis == 0);
            asset.loss_weight_sum_short = weight;
        }
    }
    markets[0].engine.asset = AssetStateV16Account::from_runtime(&asset);
    account_header.legs[0] = PortfolioLegV16Account::from_runtime(&PortfolioLegV16 {
        active: true,
        asset_index: 0,
        market_id,
        side,
        basis_pos_q: if is_short {
            -(basis as i128)
        } else {
            basis as i128
        },
        a_basis: ADL_ONE,
        k_snap: 0,
        f_snap: 0,
        kf_epoch_snap: 0,
        epoch_snap: 0,
        loss_weight: weight,
        b_snap: 0,
        b_rem: 0,
        b_epoch_snap: 0,
        b_stale: false,
        stale: false,
    });
    let mut bitmap = account_header.active_bitmap.map(V16PodU64::get);
    active_bitmap_set(&mut bitmap, 0).unwrap();
    account_header.active_bitmap = bitmap.map(V16PodU64::new);
    let risk_epoch_before = header.risk_epoch.get();
    let vault_before = header.vault;
    let c_tot_before = header.c_tot;
    let insurance_before = header.insurance;
    let capital_before = account_header.capital;
    let pnl_before = account_header.pnl;

    let mut market = MarketGroupV16ViewMut::new(&mut header, &mut markets);
    let mut account = PortfolioV16ViewMut::new(&mut account_header);
    let result = market.forfeit_recovery_leg_not_atomic(&mut account, 0, u128::MAX);
    let after = market.markets[0].engine.asset.try_to_runtime().unwrap();

    kani::cover!(
        (long_residue == 0) != (short_residue == 0),
        "forfeit drops residue left on one side only"
    );
    kani::cover!(
        long_residue != 0 && short_residue != 0,
        "forfeit drops residue left on both sides"
    );
    kani::cover!(
        long_residue == 0 && short_residue == 0,
        "forfeit resets floored sides that hold no residue"
    );
    kani::cover!(size_units == 0, "last leg is a flat pending obligation");
    kani::cover!(size_units > 1, "last leg is a multi-unit live position");
    assert_eq!(
        result,
        Ok(DeadLegForfeitOutcomeV16 {
            detached: true,
            positive_pnl_forfeited: 0,
            loss_settled: 0,
            support_consumed: 0,
            junior_face_burned: 0,
            principal_used: 0,
            insurance_used: 0,
            residual_booked: 0,
            explicit_loss: 0,
        })
    );
    assert!(active_bitmap_is_empty(
        account.header.active_bitmap.map(V16PodU64::get)
    ));
    assert_eq!((after.oi_eff_long_q, after.oi_eff_short_q), (0, 0));
    assert_eq!(
        (after.loss_weight_sum_long, after.loss_weight_sum_short),
        (0, 0)
    );
    assert_eq!(
        (after.stored_pos_count_long, after.stored_pos_count_short),
        (0, 0)
    );
    assert_eq!(
        (
            after.pending_obligation_count_long,
            after.pending_obligation_count_short
        ),
        (0, 0)
    );
    assert_eq!(
        (after.mode_long, after.mode_short),
        (SideModeV16::ResetPending, SideModeV16::ResetPending)
    );
    assert_eq!(market.header.risk_epoch.get(), risk_epoch_before + 2);
    assert_eq!(market.header.resolved_payout_blocker_count.get(), 0);
    assert_eq!(market.header.vault, vault_before);
    assert_eq!(market.header.c_tot, c_tot_before);
    assert_eq!(market.header.insurance, insurance_before);
    assert_eq!(account.header.capital, capital_before);
    assert_eq!(account.header.pnl, pnl_before);
}

// Once its loss barrier is gone, the auto-crank releases a flat pending
// obligation. When that obligation is the asset's last stored leg, the release
// leaves the asset legless with up to three atoms of unowned effective OI from
// floored A indices, the same on both sides while Live (spec.md:952). The crank
// drops that residue and starts both side resets without moving value.
#[kani::proof]
#[kani::unwind(24)]
#[kani::solver(cadical)]
fn proof_v16_public_auto_crank_release_of_last_obligation_resets_legless_asset() {
    use percolator::v16::{AutoCrankOutcomeV16, AutoCrankResultV16, AutoCrankWorkV16};

    let is_short: bool = kani::any();
    let weight_units: u8 = kani::any();
    let residue: u8 = kani::any();
    kani::assume((1..=8).contains(&weight_units));
    kani::assume(residue <= 3);
    let side = if is_short {
        SideV16::Short
    } else {
        SideV16::Long
    };
    let weight = (weight_units as u128) * POS_SCALE;

    let (mut header, mut markets, mut account_header) = one_market_view_fixture();
    install_flat_pending_obligation(
        &mut header,
        &mut markets,
        &mut account_header,
        side,
        weight,
        false,
    );
    header.vault = V16PodU128::new(7 * POS_SCALE);
    header.c_tot = V16PodU128::new(5 * POS_SCALE);
    header.insurance = V16PodU128::new(2 * POS_SCALE);
    account_header.capital = V16PodU128::new(5 * POS_SCALE);
    let mut asset = markets[0].engine.asset.try_to_runtime().unwrap();
    asset.a_long = 999_999_940_959_838;
    asset.a_short = 999_999_952_247_457;
    asset.oi_eff_long_q = residue as u128;
    asset.oi_eff_short_q = residue as u128;
    markets[0].engine.asset = AssetStateV16Account::from_runtime(&asset);
    let risk_epoch_before = header.risk_epoch.get();
    let vault_before = header.vault;
    let c_tot_before = header.c_tot;
    let insurance_before = header.insurance;
    let capital_before = account_header.capital;
    let pnl_before = account_header.pnl;

    let mut market = MarketGroupV16ViewMut::new(&mut header, &mut markets);
    let mut account = PortfolioV16ViewMut::new(&mut account_header);
    let now_slot = market.header.current_slot.get();
    let result = market.permissionless_auto_crank_not_atomic(
        &mut account,
        AutoCrankWorkV16 {
            now_slot,
            observations: &[],
            resolved_close_fee_rate_per_slot: 0,
        },
    );
    let after = market.markets[0].engine.asset.try_to_runtime().unwrap();

    kani::cover!(residue != 0, "release drops residue left on both sides");
    kani::cover!(
        residue == 0,
        "release resets floored sides that hold no residue"
    );
    kani::cover!(
        is_short && weight_units > 4,
        "release of a short obligation"
    );
    kani::cover!(
        !is_short && weight_units > 4,
        "release of a long obligation"
    );
    assert_eq!(
        result,
        Ok(AutoCrankResultV16 {
            selected: AutoCrankPlanV16::RefreshAccount {
                asset_index: Some(0)
            },
            outcome: AutoCrankOutcomeV16::Progressed(
                PermissionlessProgressOutcomeV16::AccountCurrent
            ),
        })
    );
    assert!(active_bitmap_is_empty(
        account.header.active_bitmap.map(V16PodU64::get)
    ));
    assert_eq!((after.oi_eff_long_q, after.oi_eff_short_q), (0, 0));
    assert_eq!(
        (after.loss_weight_sum_long, after.loss_weight_sum_short),
        (0, 0)
    );
    assert_eq!(
        (after.stored_pos_count_long, after.stored_pos_count_short),
        (0, 0)
    );
    assert_eq!(
        (
            after.pending_obligation_count_long,
            after.pending_obligation_count_short
        ),
        (0, 0)
    );
    assert_eq!(
        (after.mode_long, after.mode_short),
        (SideModeV16::ResetPending, SideModeV16::ResetPending)
    );
    assert_eq!(market.header.risk_epoch.get(), risk_epoch_before + 2);
    assert_eq!(market.header.resolved_payout_blocker_count.get(), 0);
    assert_eq!(market.header.vault, vault_before);
    assert_eq!(market.header.c_tot, c_tot_before);
    assert_eq!(market.header.insurance, insurance_before);
    assert_eq!(account.header.capital, capital_before);
    assert_eq!(account.header.pnl, pnl_before);
}
